'use strict';
const $=s=>document.querySelector(s), app=$('#app');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}},write=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch{toast('تعذر الحفظ في المتصفح؛ تحقق من إعدادات الخصوصية.')}};
let lang=read('sg-lang','ar'), favorites=read('sg-favs',[]),savedTrips=read('sg-trips',[]),cityRegion='الكل',onlyFav=false,tripState={from:0,to:1,date:new Date().toLocaleDateString('en-CA',{timeZone:'Europe/Stockholm'}),time:'09:00',people:1},tripReady=false,map;
const dict={ar:{home:'الرئيسية',cities:'المدن',planner:'خطّط رحلتك',tickets:'التذاكر والبطاقات',transport:'المواصلات',sights:'اكتشف',map:'الخريطة',saved:'المفضلة',budget:'الميزانية',hero:'اكتشف السويد<br>وسافر بذكاء.',sub:'من أزقة ستوكهولم إلى هدوء الشمال. مدن تستحق الزيارة، ومواصلات تفهمها، ورحلة تبدأ من هنا.',explore:'اكتشف وجهتك ←',search:'ابحث عن مدينة، معلم أو وسيلة نقل…',destinations:'وجهتك القادمة تبدأ هنا',all:'استعرض المدن ←',plan:'خطّط رحلتك',from:'من',to:'إلى',date:'تاريخ السفر',time:'الوقت',people:'المسافرون',compare:'قارن خيارات التنقل ←'},en:{home:'Home',cities:'Cities',planner:'Plan a trip',tickets:'Travel passes',transport:'Transport',sights:'Discover',map:'Map',saved:'Saved',budget:'Budget',hero:'Discover Sweden.<br>Travel smarter.',sub:'From Stockholm’s old streets to the quiet north. Find your next city and plan your journey with official sources.',explore:'Explore destinations →',search:'Search cities, attractions or transport…',destinations:'Find your next destination',all:'All destinations →',plan:'Plan your trip',from:'From',to:'To',date:'Travel date',time:'Time',people:'Travellers',compare:'Compare transport →'},sv:{home:'Hem',cities:'Städer',planner:'Planera resa',tickets:'Biljetter',transport:'Transport',sights:'Upptäck',map:'Karta',saved:'Sparat',budget:'Budget',hero:'Upptäck Sverige.<br>Res smartare.',sub:'Från Stockholms gränder till lugnet i norr. Upptäck resmål och planera resan med officiella källor.',explore:'Upptäck resmål →',search:'Sök stad, sevärdhet eller transport…',destinations:'Hitta ditt nästa resmål',all:'Alla resmål →',plan:'Planera din resa',from:'Från',to:'Till',date:'Resdatum',time:'Tid',people:'Resenärer',compare:'Jämför transport →'}};
const t=k=>dict[lang][k]||dict.ar[k]||k;
const norm=s=>s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f\u064B-\u065F]/g,'').replace(/[أإآ]/g,'ا').replace(/ة/g,'ه');
function toast(m){$('#toast').textContent=m;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3500)}
function external(url,label,cls='btn'){return `<a class="${cls}" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`}
function distance(a,b){const r=Math.PI/180,dlat=(b.lat-a.lat)*r,dlon=(b.lon-a.lon)*r;return Math.round(6371*2*Math.asin(Math.sqrt(Math.sin(dlat/2)**2+Math.cos(a.lat*r)*Math.cos(b.lat*r)*Math.sin(dlon/2)**2)))}
function directions(a,b,mode='transit'){return `https://www.google.com/maps/dir/?api=1&origin=${a.lat},${a.lon}&destination=${b.lat},${b.lon}&travelmode=${mode}`}
function mapLink(p){return `https://www.google.com/maps/search/?api=1&query=${p.lat},${p.lon}`}
function resrobot(){const a=cities[tripState.from],b=cities[tripState.to],triple=p=>`A=16@X=${Math.round(p.lon*1e6)}@Y=${Math.round(p.lat*1e6)}@O=${p.name}`;return 'https://reseplanerare.resrobot.se/bin/query.exe/sn?'+new URLSearchParams({SID:triple(a),ZID:triple(b),date:tripState.date,time:tripState.time,timesel:'depart',start:'1'})}
function nav(){const names=['home','cities','planner','tickets','transport','sights','map','saved'];$('#nav').innerHTML=names.map(n=>`<a href="#${n}" class="${(location.hash.slice(1).split('?')[0]||'home')===n?'active':''}">${t(n)}</a>`).join('');$('#lang').value=lang;document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.body.classList.toggle('dark',read('sg-dark',false));document.body.style.fontSize=read('sg-large',false)?'21px':''}
function cityOptions(sel){return cities.map(c=>`<option value="${c.id}" ${c.id==sel?'selected':''}>${c.name}${lang==='ar'?' — '+c.ar.split(' ')[0]:''}</option>`).join('')}
function cityInput(id,selected){return `<input id="${id}" list="trip-cities" value="${esc(cities[selected].name)}" placeholder="اكتب اسم المدينة بالعربية أو السويدية" autocomplete="off" required aria-label="${id==='from'?t('from'):t('to')}" aria-describedby="city-input-help">`}
function resolveCity(value){const q=norm(value.trim());return cities.find(c=>[c.name,c.ar,...c.ar.split(' ')].some(n=>norm(n)===q))}
function tripForm(){return `<form id="tripform"><p id="city-input-help" class="muted">اكتب اسم المدينة أو اخترها من الاقتراحات؛ مثل Stockholm أو ستوكهولم.</p><datalist id="trip-cities">${cities.map(c=>`<option value="${esc(c.name)}">${c.ar}</option><option value="${esc(c.ar)}">${c.name}</option>`).join('')}</datalist><div class="formgrid"><label>${t('from')}${cityInput("from",tripState.from)}</label><button type="button" class="swap" id="swap" aria-label="عكس المسار">⇄</button><label>${t('to')}${cityInput("to",tripState.to)}</label><label>${t('date')}<input type="date" id="date" required value="${esc(tripState.date)}"></label><label>${t('time')}<input type="time" id="time" required value="${esc(tripState.time)}"></label><label>${t('people')}<input id="people" type="number" min="1" max="20" value="${tripState.people}" required></label></div><div class="row" style="margin-top:18px"><span class="small muted">${lang==='ar'?'أسعار موثقة حيث تتوفر • وروابط الشركات للتحقق':'Official booking sources • no invented fares or timetables'}</span><button class="primary" type="submit">${t('compare')}</button></div></form>`}
function wireTrip(){const form=$('#tripform');if(!form)return;$('#swap').onclick=()=>{const v=$('#from').value;$('#from').value=$('#to').value;$('#to').value=v};form.onsubmit=e=>{e.preventDefault();const origin=resolveCity($('#from').value),destination=resolveCity($('#to').value);if(!origin||!destination){toast('اختر مدينة من الاقتراحات أو اكتب اسمها الكامل.');(!origin?$('#from'):$('#to')).focus();return}if(origin.id===destination.id){toast('اختر مدينتين مختلفتين / Choose two different cities');return}tripState={from:origin.id,to:destination.id,date:$('#date').value,time:$('#time').value,people:+$('#people').value};tripReady=true;if(location.hash==='#planner'){render()}else location.hash='planner'}}
function cityCard(c){return `<article class="card"><div class="cover" data-cityimg="${c.id}"><span class="region">${c.region==='شمال'?'NORTHERN SWEDEN':c.region==='وسط'?'CENTRAL SWEDEN':'SOUTHERN SWEDEN'}</span><button class="fav ${favorites.includes(c.id)?'on':''}" data-fav="${c.id}" aria-label="حفظ ${c.name}" aria-pressed="${favorites.includes(c.id)}">${favorites.includes(c.id)?'♥':'♡'}</button></div><div class="cardbody"><h3 dir="ltr">${c.name}</h3><div class="small muted">${c.ar}</div><p>${c.desc}</p><div class="stats"><span>⌖ ${distance(cities[0],c)} كم</span><span>${c.local}</span></div><a class="btn" href="#city/${c.id}">${lang==='ar'?'اكتشف المدينة':'Explore city'} ←</a></div></article>`}
function wireFav(){document.querySelectorAll('[data-fav]').forEach(b=>b.onclick=()=>{const id=+b.dataset.fav;favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];write('sg-favs',favorites);b.classList.toggle('on',favorites.includes(id));b.textContent=favorites.includes(id)?'♥':'♡';b.setAttribute('aria-pressed',favorites.includes(id));if(location.hash==='#saved')render()})}
function cityImages(){document.querySelectorAll('[data-cityimg]').forEach(el=>{const c=cities[+el.dataset.cityimg],d=cityPhotos[c.id];if(d)insertImage(el,d,c.name)})}
function insertImage(el,d,name){if(el.querySelector('img'))return;const im=document.createElement('img');im.alt=d.alt||name;im.loading='lazy';im.decoding='async';im.width=d.width;im.height=d.height;im.src=d.url;im.onerror=()=>{if(!im.dataset.retried){im.dataset.retried='1';im.src=d.url+'?v=4';return}im.remove();const message=document.createElement('span');message.className='photo-unavailable';message.textContent='تعذّر تحميل الصورة';el.append(message)};el.prepend(im);const caption=document.createElement('span');caption.className='credit photo-credit';const a=document.createElement('a');a.href=d.credit;a.target='_blank';a.rel='noopener noreferrer';a.textContent=(d.artist||'Wikimedia Commons');a.title=d.file;const l=document.createElement('a');l.href=d.licenseUrl||d.credit;l.target='_blank';l.rel='noopener noreferrer';l.textContent=d.license;caption.append(a,' · ',l);el.append(caption)}
function photoCredits(){return '<section class="panel"><h2>مصادر صور المدن</h2><p>صور محددة لكل مدينة ومحفوظة مع الموقع. جرى تصغيرها وتحويلها إلى WebP، وتُعرض بقصّ متجاوب داخل البطاقات. ترخيص كل صورة مستقل عن ترخيص الموقع.</p><ul class="photo-sources">'+Object.values(cityPhotos).map(d=>'<li><b dir="ltr">'+esc(d.name)+'</b> — '+esc(d.artist||'Wikimedia Commons')+' · '+external(d.credit,'الصورة الأصلية','small')+' · '+external(d.licenseUrl||d.credit,d.license,'small')+'</li>').join('')+'</ul></section>'}
function home(){app.innerHTML=`<section class="hero"><div class="eyebrow">YOUR SWEDISH JOURNEY STARTS HERE</div><h1>${t('hero')}</h1><p>${t('sub')}</p><a href="#cities" class="btn">${t('explore')}</a><a class="credit hero-photo-credit" href="${esc(cityPhotos[0].credit)}" target="_blank" rel="noopener">Stockholm · ${esc(cityPhotos[0].artist)} · ${esc(cityPhotos[0].license)}</a></section><div class="wrap"><section class="planner-box"><h2 style="font-size:21px;margin:0 0 15px">${t('plan')}</h2>${tripForm()}</section><div class="featurestrip"><div><b>22 وجهة لاستكشافها</b><p>مدن كبرى، جزر هادئة وطبيعة شمالية.</p></div><div><b>رحلتك، بطريقتك</b><p>قطارات وحافلات وقوارب ومصادر الحجز.</p></div><div><b>معلومات واضحة المصدر</b><p>نوضح ما تحققنا منه وما يحتاج إلى تأكيد.</p></div></div><div class="sectionhead row"><div><div class="eyebrow" style="color:#9c792a">EXPLORE SWEDEN</div><h2>${t('destinations')}</h2><p>من المدن النابضة بالحياة إلى الطبيعة التي تستحق الرحلة.</p></div><a href="#cities">${t('all')}</a></div><form id="globalform" class="row"><input id="globalsearch" class="search" placeholder="${t('search')}" aria-label="البحث الشامل"><button class="primary">${lang==='ar'?'بحث':'Search'}</button></form><div class="chips">${['الكل','وسط','جنوب','شمال'].map(x=>`<button class="chip ${x===cityRegion?'selected':''}" data-region="${x}">${x==='الكل'?'كل الوجهات':x+' السويد'}</button>`).join('')}</div><div class="grid" id="homecities">${cities.filter(c=>cityRegion==='الكل'||c.region===cityRegion).slice(0,6).map(cityCard).join('')}</div><section class="panel row" style="margin-top:35px;background:var(--blue);color:white"><div><span class="eyebrow">A LITTLE PLANNING. A GREAT JOURNEY.</span><h2>رحلة جميلة تبدأ بخطة بسيطة.</h2><p>احسب ميزانيتك، احفظ مدنك المفضلة، وانطلق.</p></div><a href="#budget" class="btn yellow">احسب ميزانيتك ←</a></section></div>`;wireTrip();wireFav();cityImages();document.querySelectorAll('[data-region]').forEach(b=>b.onclick=()=>{cityRegion=b.dataset.region;home()});$('#globalform').onsubmit=e=>{e.preventDefault();location.hash='search?q='+encodeURIComponent($('#globalsearch').value)};window.SGMotion?.mountHome()}
function citiesPage(){app.innerHTML=`<div class="wrap"><div class="sectionhead"><div class="eyebrow" style="color:#9c792a">DESTINATIONS</div><h1 class="page-title">${t('cities')}</h1><p>22 مدينة • المسافات من Stockholm بخط مستقيم، وليست مسافات القيادة.</p></div><div class="row"><input class="search" id="citysearch" placeholder="Stockholm، ستوكهولم، Göteborg…" aria-label="بحث المدن"><select id="region" style="max-width:200px">${['الكل','وسط','جنوب','شمال'].map(x=>`<option ${x===cityRegion?'selected':''}>${x}</option>`).join('')}</select><button id="favonly" aria-pressed="${onlyFav}">${onlyFav?'♥':'♡'} المفضلة فقط</button></div><p id="count" class="muted small"></p><div id="citygrid" class="grid"></div></div>`;const update=()=>{const q=norm($('#citysearch').value),list=cities.filter(c=>(cityRegion==='الكل'||c.region===cityRegion)&&(!onlyFav||favorites.includes(c.id))&&norm(c.name+' '+c.ar+' '+c.sights.join(' ')).includes(q));$('#count').textContent=list.length+' نتيجة';$('#citygrid').innerHTML=list.length?list.map(cityCard).join(''):'<div class="empty">لا توجد نتائج. جرّب اسمًا آخر أو غيّر الفلاتر.</div>';wireFav();cityImages()};$('#citysearch').oninput=update;$('#region').onchange=e=>{cityRegion=e.target.value;update()};$('#favonly').onclick=()=>{onlyFav=!onlyFav;$('#favonly').setAttribute('aria-pressed',onlyFav);$('#favonly').textContent=(onlyFav?'♥':'♡')+' المفضلة فقط';update()};update()}
function cityPage(id){const c=cities[id];if(!c){notfound();return}app.innerHTML=`<div class="wrap"><a href="#cities">← ${t('cities')}</a><div class="row"><div><h1 class="page-title" dir="ltr">${c.name}</h1><p>${c.ar} · ${c.region} السويد</p></div><button data-fav="${id}" class="fav ${favorites.includes(id)?'on':''}" style="position:static" aria-label="حفظ المدينة">${favorites.includes(id)?'♥':'♡'}</button></div><div class="split"><div><div class="cover" data-cityimg="${id}" style="height:320px;border-radius:12px"><span class="region">${c.name}</span></div><h2>عن المدينة</h2><p>${c.desc}</p><div class="panel"><h3>المعالم والطبيعة</h3>${c.sights.map(n=>`<p>${esc(n)} ${external('https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(n+' '+c.name),'الموقع','small')}</p>`).join('')}<p>راجع المصدر السياحي الرسمي لتاريخ المعالم وساعات العمل والأنشطة العائلية.</p>${external(c.url,'دليل المدينة الرسمي')}</div><div class="panel"><h3>الصناعات والتعليم</h3><p>${c.industry}</p><h3>المواسم والطقس</h3><p>${c.region==='شمال'?'الصيف للضوء الطويل والطبيعة، والشتاء للأنشطة الثلجية. رؤية الشفق غير مضمونة وتتأثر بالسحب والنشاط الشمسي.':'الصيف مناسب للمشي والأنشطة الخارجية، والشتاء للمتاحف والتجارب الداخلية. تختلف ساعات الافتتاح بحسب الموسم.'}</p>${external('https://www.smhi.se/en','توقعات SMHI')}</div></div><aside><div class="panel"><h3>معلومات الزيارة</h3><p><b>${distance(cities[0],c)} كم</b> من Stockholm</p><p class="small muted">مسافة بخط مستقيم محسوبة من إحداثيات مراكز المدن؛ ليست مسافة الطريق.</p><hr><p>عدد السكان: <b>${c.pop?c.pop.toLocaleString('en-US'):'يحتاج إلى تحقق'}</b></p><p class="small muted">${c.pop?'التجمع الحضري (tätort)، 31 ديسمبر 2023؛ لا يمثل البلدية. آخر تحقق من المصدر: 15 أكتوبر 2026.':'لم نُدخل رقمًا غير متحقق. راجع SCB للمدينة والبلدية والسنة المطلوبة.'}</p>${external(SCB,'المصدر: SCB','small')}<p>النقل المحلي: <b>${c.local}</b></p><p class="small muted">مدة الوصول والأسعار والتبديلات تُراجع حسب التاريخ في مخطط الرحلات الرسمي.</p><button id="go-city" class="primary">خطّط رحلة إلى ${c.name}</button></div><iframe title="خريطة ${c.name}" width="100%" height="300" style="border:0;border-radius:12px" loading="lazy" src="https://www.openstreetmap.org/export/embed.html?bbox=${c.lon-.08}%2C${c.lat-.04}%2C${c.lon+.08}%2C${c.lat+.04}&layer=mapnik&marker=${c.lat}%2C${c.lon}"></iframe>${external(mapLink(c),'افتح في الخرائط')}<p class="small muted">© OpenStreetMap contributors</p></aside></div></div>`;$('#go-city').onclick=()=>{tripState.to=c.id;tripState.from=c.id===0?1:0;tripReady=true;location.hash='planner'};wireFav();cityImages()}
function planner(){app.innerHTML=`<div class="wrap"><div class="sectionhead"><h1 class="page-title">${t('planner')}</h1><p>اختَر وجهتك، قارن مصادر التنقل، وابنِ برنامج زيارتك.</p></div><section class="panel">${tripForm()}</section><div id="results">${tripReady?tripResults():''}</div><div class="panel"><h2>برنامج زيارة من يوم إلى خمسة</h2><div class="formgrid" style="grid-template-columns:repeat(4,1fr)"><label>الوجهة<select id="it-city">${cityOptions(tripState.to)}</select></label><label>عدد الأيام<input type="number" min="1" max="5" value="2" id="it-days"></label><label>اهتماماتك<select id="it-interest"><option>متنوعة</option><option>ثقافة وتاريخ</option><option>طبيعة ومشي</option><option>عائلة وأطفال</option></select></label><label>الميزانية<select id="it-budget"><option>اقتصادية</option><option>متوسطة</option><option>مرنة</option></select></label></div><button class="primary" id="makeplan" style="margin-top:20px">اقترح برنامج الزيارة</button><div id="itinerary"></div></div></div>`;wireTrip();if(tripReady)wireResults();$('#makeplan').onclick=makePlan}
function tripResults(){const a=cities[tripState.from],b=cities[tripState.to];return `<section class="panel"><div class="row"><h2 dir="ltr">${a.name} → ${b.name}</h2><button id="save-trip">♡ احفظ الرحلة</button></div><p>${esc(tripState.date)} · ${esc(tripState.time)} · ${tripState.people} مسافر • ${distance(a,b)} كم بخط مستقيم</p><div class="note">هذه مقارنة لمصادر البحث، وليست عروض رحلات مؤكدة. لا يتصل التطبيق حاليًا بواجهة مواعيد أو أسعار. تُرسل مدينتا الانطلاق والوصول والتاريخ والوقت إلى ResRobot؛ أعد إدخال عدد المسافرين وفئاتهم عند الحجز.</div>${external(resrobot(),'اعرض المواعيد الفعلية لدى ResRobot','btn primary')}<div class="row" style="margin-top:20px"><label>ترتيب المقارنة <select id="sort"><option value="default">وسائل التنقل</option><option value="price">الأرخص</option><option value="duration">الأسرع</option><option value="changes">الأقل تبديلًا</option></select></label><span class="small muted" id="sortnote">لا ترتيب رقمي دون بيانات مؤكدة</span></div><div class="tablewrap"><table><thead><tr><th>الوسيلة</th><th>السعر والرابط الرسمي</th><th>المدة / التبديلات</th><th>المسافة البرية</th><th>البحث والحجز</th></tr></thead><tbody>${[['🚆','قطار','https://www.sj.se/en'],['🚌','حافلة','https://www.flixbus.se/'],['✈','طيران','https://www.swedavia.com/'],['🚗','سيارة',directions(a,b,'driving')],...(b.name==='Visby'||a.name==='Visby'?[['⛴','عبّارة','https://www.destinationgotland.se/en']]:[])].map(r=>`<tr><td>${r[0]} ${r[1]}</td><td><b>سعر متغيّر حسب الرحلة</b><br>${external(r[2],'اعرض السعر الآن','price-source')}</td><td>غير متاحة؛ راجع المصدر</td><td>راجع المسار</td><td>${external(r[2],r[1]==='سيارة'?'المسار البري':'المصدر الرسمي','small')}</td></tr>`).join('')}</tbody></table></div><p class="small muted">الروابط لا تثبت توفر خدمة مباشرة بين المدينتين. الطيران قد يتطلب مطارات بديلة ونقلًا إضافيًا. موانئ Gotland تتطلب الوصول برًا إلى الميناء.</p>${external(directions(a,b),'المسار بالمواصلات العامة')}</section>`}
function wireResults(){$('#save-trip').onclick=()=>{const key=JSON.stringify(tripState);if(!savedTrips.some(s=>JSON.stringify(s)===key)){savedTrips.push({...tripState});write('sg-trips',savedTrips)}toast('حُفظت الرحلة في هذا المتصفح')};$('#sort').onchange=()=>{$('#sortnote').textContent='لا يمكن تحديد الأرخص أو الأسرع أو الأقل تبديلًا دون بيانات فعلية. افتح ResRobot للمقارنة.';toast('البيانات اللازمة للترتيب غير متاحة حاليًا')}}
function makePlan(){const c=cities[+$('#it-city').value],days=Math.max(1,Math.min(5,+$('#it-days').value||1)),interest=$('#it-interest').value,budget=$('#it-budget').value;$('#it-days').value=days;let stops=[...c.sights];if(interest==='طبيعة ومشي')stops.reverse();const plan={city:c.id,days,interest,budget};const rows=Array.from({length:days},(_,i)=>{const n=stops[i%stops.length];return `<div class="day"><b>اليوم ${i+1} — ${i<3?esc(n):'استكشاف أعمق ووقت حر'}</b><p>${i<3?`ابدأ بزيارة ${esc(n)}، ثم استراحة ومشي في المنطقة المحيطة.`:'خصص اليوم لأحياء إضافية أو نشاط تختاره من الموقع السياحي الرسمي.'} ${interest==='عائلة وأطفال'?'قسّم الزيارة إلى فترات قصيرة، مع وقت للعب والراحة.':interest==='ثقافة وتاريخ'?'ابحث عن جولة أو متحف قريب حسب ساعات العمل.':interest==='طبيعة ومشي'?'اختر مسار مشي مناسبًا للطقس وقدرتك الجسدية.':'اترك وقتًا للتصوير والتجربة المحلية.'}</p>${external('https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(n+' '+c.name),'الموقع','small')}</div>`}).join('');$('#itinerary').innerHTML=`<h3>اقتراح ${days} أيام في ${c.name}</h3><p class="badge">${interest} · ميزانية ${budget}</p><p class="small muted">اقتراح سياحي، لا يتضمن حجوزات أو تحققًا من ساعات العمل والمسافات بين نقاط الزيارة.</p>${rows}<p>${budget==='اقتصادية'?'ركّز على المشي والمساحات العامة، وتحقق من رسوم المعالم.':budget==='متوسطة'?'اختر نشاطًا مدفوعًا يوميًا بعد مراجعة سعره، مع وقت للمشي.':'يمكنك إضافة جولات مرشدة وتجارب خاصة بعد التحقق من توفرها.'}</p><div class="row"><button id="shareplan" class="primary">مشاركة الخطة</button><a class="btn" href="#budget">احسب ميزانيتك</a>${external(c.url,'تحقق من الزيارات')}</div>`;$('#shareplan').onclick=()=>sharePlan(plan)}
async function sharePlan(p){const c=cities[p.city],url=location.origin+'./#planner?plan='+encodeURIComponent(JSON.stringify(p)),text=`اقتراح زيارة ${c.name} — ${p.days} أيام — ${p.interest} — ${p.budget}\n`+c.sights.join('، ');try{if(navigator.share){await navigator.share({title:'Stockholm Guide',text,url})}else{await navigator.clipboard.writeText(text+'\n'+url);toast('تم نسخ الخطة ورابطها')}}catch(e){if(e.name!=='AbortError'){showModal(`<h2>مشاركة الخطة</h2><textarea style="width:100%;min-height:150px" readonly>${esc(text+'\n'+url)}</textarea><p>انسخ النص والرابط لمشاركتهما.</p>`)}}}

const verifiedFares={SL:{rows:[['رحلة واحدة — بالغ، 75 دقيقة','43'],['رحلة واحدة — مخفّض، وفق الأهلية','26']],url:'https://sl.se/en/fares-and-tickets/visitor-tickets/single-journey-tickets',detail:'السعر المنشور عند التحقق في 15 أكتوبر 2026؛ رسوم المطار والخدمات الخاصة قد تختلف.'},'Västtrafik':{rows:[['رحلة واحدة — بالغ، منطقة واحدة','38']],url:'https://www.vasttrafik.se/om-vasttrafik/nyhetsarkiv/nyapriser/',detail:'السعر الأساسي المعلن اعتبارًا من 9 يونيو 2026؛ تحقق من المناطق وطريقة الشراء.'}};
function fareBlock(name,url){const f=verifiedFares[name];return `<div class="farebox">${f?f.rows.map(r=>`<div class="fareline"><span>${r[0]}</span><strong class="price" dir="ltr">${r[1]} SEK</strong></div>`).join(''):`<p><b>السعر يتحدد حسب المنطقة ونوع التذكرة.</b></p>`}<p class="small muted">${f?f.detail+' آخر تحقق: 15 أكتوبر 2026.':'اختر مسارك وفئة المسافر في موقع الشركة لعرض السعر الآن.'}</p>${external(f?f.url:url,'تحقق من السعر الآن لدى '+esc(name),'btn price-source')}</div>`}
function ticketsPage(){app.innerHTML=`<div class="wrap"><h1 class="page-title">${t('tickets')}</h1><p class="muted">شبكات محلية وإقليمية؛ قد تختلف الصلاحية حسب المناطق والمسار.</p><div class="note">الأسعار الموثقة أدناه هي الأسعار المنشورة عند آخر تحقق، وليست تحديثًا مباشرًا. بجانب كل بطاقة رابط الشركة لعرض السعر الآن. تختلف الأسعار حسب المناطق والعمر ونوع التذكرة.</div><div class="row"><input id="ticketsearch" class="search" placeholder="SL، UL، Skåne…" aria-label="بحث شبكات التذاكر"><a class="btn primary" href="#passcompare">قارن بطاقات الزيارة</a></div><div class="grid" id="ticketgrid" style="margin-top:25px"></div></div>`;const update=()=>{const q=norm($('#ticketsearch').value),list=tickets.filter(t=>norm(t.join(' ')).includes(q));$('#ticketgrid').innerHTML=list.length?list.map(t=>`<article class="card cardbody"><span class="badge">${t[1]}</span><h2 dir="ltr">${t[0]}</h2>${fareBlock(t[0],t[2])}<p>راجع أنواع التذاكر، مناطق الصلاحية والتخفيضات في مصدر الشركة.</p><button class="btn" data-ticket="${tickets.indexOf(t)}">أنواع التذاكر والشروط ←</button>${external(t[2],'المصدر والشراء الرسمي')}</article>`).join(''):'<p class="empty">لا توجد شبكة مطابقة.</p>';document.querySelectorAll('[data-ticket]').forEach(b=>b.onclick=()=>ticketModal(tickets[+b.dataset.ticket]))};$('#ticketsearch').oninput=update;update()}
function ticketModal(t){showModal(`<h2>${t[0]} — ${t[1]}</h2>${fareBlock(t[0],t[2])}<p>الصلاحية الدقيقة تعتمد على المناطق وخط الرحلة. لا نفترض توفر كل نوع لدى كل شبكة.</p><div class="tablewrap"><table><thead><tr><th>الفئة المطلوب التحقق منها</th><th>السعر والرابط الرسمي</th><th>حالة التوفر</th></tr></thead><tbody>${['رحلة واحدة','24 ساعة','عدة أيام','30 يومًا','اشتراكات طويلة','أطفال / طلاب / كبار السن','سياحية / عائلية'].map(n=>`<tr><td>${n}</td><td>${external(t[2],'السعر الآن لدى الشركة','price-source')}</td><td>حسب المنطقة والفئة</td></tr>`).join('')}</tbody></table></div><p>تحقق من تفعيل التذكرة، مدة الصلاحية، المناطق، إثبات الطالب أو العمر، وشروط المرافقين وإعادة الشراء. مكان الشراء وطريقته حسب الشركة.</p>${external(t[2],'التذاكر والأسعار والشروط الرسمية')}`)}
function passCompare(){app.innerHTML=`<div class="wrap"><h1 class="page-title">قارن بطاقات الزيارة</h1><p>أدخل الأسعار التي تراها الآن في موقع شركة النقل؛ الحاسبة لا تفترض أسعارًا أو صلاحية.</p><form class="panel" id="passform"><div class="formgrid" style="grid-template-columns:repeat(3,1fr)"><label>الشبكة<select id="passnetwork">${tickets.map((t,i)=>`<option value="${i}">${t[0]}</option>`).join('')}</select></label><label>مدة الزيارة بالأيام<input type="number" min="1" max="30" value="3" id="passdays" required></label><label>رحلات في اليوم<input type="number" min="1" max="30" value="3" id="passrides" required></label><label>سعر الرحلة الواحدة SEK<input type="number" min="0" step="0.01" id="singleprice" required></label><label>سعر بطاقة 24 ساعة SEK<input type="number" min="0" step="0.01" id="dayprice" required></label><label>سعر اشتراك يغطي الزيارة SEK<input type="number" min="0" step="0.01" id="periodprice" required></label></div><p>${external(tickets[0][2],'تحقق من الأسعار','small')}</p><button class="primary">احسب المقارنة</button></form><div id="passresult"></div></div>`;$('#passnetwork').onchange=()=>{$('#passform p').innerHTML=external(tickets[+$('#passnetwork').value][2],'تحقق من الأسعار','small');['singleprice','dayprice','periodprice'].forEach(id=>$('#'+id).value='');$('#passresult').innerHTML=''};$('#passform').onsubmit=e=>{e.preventDefault();const days=+$('#passdays').value,r=+$('#passrides').value,rows=[['رحلات منفردة',days*r*+$('#singleprice').value],['بطاقات يومية',days*+$('#dayprice').value],['اشتراك يغطي الزيارة',+$('#periodprice').value]].sort((a,b)=>a[1]-b[1]);$('#passresult').innerHTML=`<div class="panel"><h2>الأقل تكلفة حسب مدخلاتك: ${rows[0][0]}</h2>${rows.map(r=>`<p>${r[0]}: <b>${r[1].toFixed(2)} SEK</b></p>`).join('')}<p class="small muted">مقارنة حسابية لمسافر واحد، تفترض نفس المناطق والصلاحية الكافية. عدد الرحلات لا يساوي دائمًا عدد التذاكر بسبب التحويلات ضمن مدة الصلاحية.</p></div>`}}
function transportPage(){app.innerHTML=`<div class="wrap"><h1 class="page-title">${t('transport')}</h1><p>قطار، مترو، ترام، حافلة، سفينة، طائرة أو تنقل مشترك.</p><div class="row"><input id="opsearch" class="search" aria-label="بحث الشركات" placeholder="SJ، قطار، سفينة…"><select id="optype" style="max-width:220px">${['الكل','قطار','محلي','سفينة','طيران','حافلة','إضافي'].map(n=>`<option>${n}</option>`).join('')}</select></div><div class="grid" id="opgrid" style="margin-top:25px"></div><div class="note">إمكانية الوصول: تختلف حسب المركبة والمحطة والمساعدة المحجوزة. راجع صفحة المشغّل قبل السفر، خاصةً عند استخدام كرسي متحرك. المسار والمحطات والمواعيد متاحة عبر البحث الرسمي.</div></div>`;const update=()=>{const q=norm($('#opsearch').value),type=$('#optype').value;$('#opgrid').innerHTML=operators.filter(o=>(type==='الكل'||o[1]===type)&&norm(o.join(' ')).includes(q)).map(o=>`<article class="card cardbody"><span class="badge">${o[1]}</span><h2 dir="ltr">${o[0]}</h2><p>${o[2]}</p><p class="small muted">المواعيد والأسعار والمسارات الدقيقة: لدى المشغّل. قيود الأمتعة والإلغاء والوصول تختلف حسب الخدمة.</p>${external(o[3],'المسارات والحجز والشروط')}<a class="btn" href="#planner">ابحث عن مسار ←</a></article>`).join('')||'<p class="empty">لا توجد نتائج.</p>'};$('#opsearch').oninput=update;$('#optype').onchange=update;update()}
function sightCard(s){return `<article class="card cardbody"><span class="badge">${s.cat} · ${cities[s.city].name}</span><h3 dir="ltr" style="margin-top:12px">${s.name}</h3><p>${s.desc}</p><button data-sight="${s.id}" class="btn">تفاصيل الزيارة والوصول ←</button></article>`}
function sightsPage(){app.innerHTML=`<div class="wrap"><h1 class="page-title">معالم وتجارب تستحق الرحلة</h1><p class="muted">اختَر تجربة، ثم تحقّق من الافتتاح والتذكرة من مصدرها الرسمي.</p><div class="row"><input id="sightsearch" class="search" placeholder="ابحث عن معلم أو مدينة…" aria-label="بحث المعالم"><select id="sightcat" style="max-width:220px">${['الكل','تاريخية','قصور','متاحف','جزر','طبيعة','مجانية','عائلية','شتوية'].map(n=>`<option>${n}</option>`).join('')}</select></div><div id="sightgrid" class="grid" style="margin-top:25px"></div></div>`;const update=()=>{const q=norm($('#sightsearch').value),cat=$('#sightcat').value;$('#sightgrid').innerHTML=sights.filter(s=>(cat==='الكل'||cat===s.cat)&&norm(s.name+' '+s.desc+' '+cities[s.city].name+' '+cities[s.city].ar).includes(q)).map(sightCard).join('')||'<p class="empty">لا توجد نتائج.</p>';wireSights()};$('#sightsearch').oninput=update;$('#sightcat').onchange=update;update()}
function wireSights(){document.querySelectorAll('[data-sight]').forEach(b=>b.onclick=()=>{const s=sights[+b.dataset.sight];showModal(`<span class="badge">${s.cat} · ${cities[s.city].name}</span><h2 dir="ltr">${s.name}</h2><p>${s.desc}</p><p>العنوان / نقطة البحث: ${s.address}</p><p>الوصول: افتح مسار المواصلات من مركز المدينة؛ المواعيد تعتمد على التاريخ والوقت.</p>${external(directions(cities[s.city],s),'مسار الوصول')}${external(s.url,'المصدر الرسمي')}<iframe title="خريطة المعلم" loading="lazy" width="100%" height="280" style="border:0;margin-top:15px" src="https://www.openstreetmap.org/export/embed.html?bbox=${s.lon-.02}%2C${s.lat-.01}%2C${s.lon+.02}%2C${s.lat+.01}&layer=mapnik&marker=${s.lat}%2C${s.lon}"></iframe><p class="small muted">الصور المرخّصة للمعلم لم تُضف بعد. لم نستخدم صورة لمكان آخر.</p>`)})}
function showModal(html){$('#modalContent').innerHTML=html;$('#modal').showModal()}
$('#close').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});
function mapPage(){app.innerHTML=`<div class="wrap"><div class="row"><div><h1 class="page-title">${t('map')}</h1><p>مدن ومحطات ومطارات وموانئ ومعالم • نقاط إرشادية وليست حالة تشغيل حية.</p></div><button class="primary" id="nearby">⌖ أماكن قريبة مني</button></div><div class="row" style="margin-bottom:20px"><select id="maptype" style="max-width:260px">${['الكل','مدن','معالم','مطارات','محطات','موانئ'].map(n=>`<option>${n}</option>`).join('')}</select><span id="geostatus" role="status" class="small muted"></span></div><div class="map-layout"><div class="map-list" id="maplist"></div><div><div id="map"></div><p class="small muted">© OpenStreetMap contributors · الإحداثيات إرشادية؛ افتح الخرائط لتأكيد المدخل الصحيح.</p></div></div></div>`;const points=[...cities.map(c=>({...c,type:'مدن'})),...sights.map(s=>({...s,type:'معالم'})),...extraPoints.map(r=>({name:r[0],lat:r[1],lon:r[2],type:r[3]}))];let markers=[],layer;const haveMap=typeof L!=='undefined';if(haveMap){map=L.map('map').setView([62,16],5);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors',maxZoom:18}).addTo(map);layer=L.layerGroup().addTo(map)}else $('#map').innerHTML='<div class="empty">تعذر تحميل الخريطة. يمكنك استخدام قائمة المواقع وروابط الخرائط مباشرة.</div>';function update(origin){const pts=points.filter(p=>$('#maptype').value==='الكل'||p.type===$('#maptype').value).sort((a,b)=>origin?distance(origin,a)-distance(origin,b):0);if(layer)layer.clearLayers();markers=[];$('#maplist').innerHTML=pts.map((p,i)=>`<button data-point="${i}"><span dir="auto">${esc(p.name)}</span><span class="small">${origin?distance(origin,p)+' كم':p.type}</span></button>`).join('');pts.forEach((p,i)=>{if(layer){const marker=L.marker([p.lat,p.lon]).bindPopup(`<b>${esc(p.name)}</b><p>${esc(p.type)}</p><a href="${mapLink(p)}" target="_blank" rel="noopener">الموقع والمسار ↗</a>`);marker.addTo(layer);markers.push(marker)}});document.querySelectorAll('[data-point]').forEach(b=>b.onclick=()=>{const i=+b.dataset.point;if(map&&markers[i]){map.setView([pts[i].lat,pts[i].lon],12);markers[i].openPopup()}else window.open(mapLink(pts[i]),'_blank','noopener')})}$('#maptype').onchange=()=>update();update();$('#nearby').onclick=()=>{if(!navigator.geolocation){$('#geostatus').textContent='تحديد الموقع غير مدعوم في هذا المتصفح.';return}$('#geostatus').textContent='بانتظار إذن تحديد الموقع…';navigator.geolocation.getCurrentPosition(p=>{const o={lat:p.coords.latitude,lon:p.coords.longitude};$('#geostatus').textContent='تم ترتيب المواقع حسب قربها بخط مستقيم. لا نرسل موقعك إلى خادمنا.';update(o);if(map){L.circleMarker([o.lat,o.lon],{radius:10,color:'#d09611'}).addTo(map).bindPopup('موقعك التقريبي');map.setView([o.lat,o.lon],10)}},e=>{$('#geostatus').textContent=e.code===1?'لم يُمنح إذن الموقع. يمكنك اختيار موقع من القائمة.':'تعذر تحديد الموقع؛ تأكد من تفعيل الخدمة وحاول مجددًا.'},{timeout:12000,maximumAge:60000})}}
function savedPage(){app.innerHTML=`<div class="wrap"><h1 class="page-title">${t('saved')}</h1><p>محفوظة في هذا المتصفح؛ قد تُحذف عند مسح بياناته.</p><h2>المدن المحفوظة</h2><div class="grid">${favorites.length?favorites.map(id=>cities[id]).filter(Boolean).map(cityCard).join(''):'<p class="empty">اضغط ♡ على أي مدينة لحفظها. <a href="#cities">اكتشف المدن ←</a></p>'}</div><h2>رحلاتك</h2>${savedTrips.map((s,i)=>`<div class="panel row"><div><b dir="ltr">${cities[s.from]?.name} → ${cities[s.to]?.name}</b><p>${esc(s.date)} · ${esc(s.time)} · ${s.people} مسافر</p></div><button data-open-trip="${i}" class="primary">افتح الرحلة</button><button data-delete-trip="${i}">إزالة</button></div>`).join('')||'<p>لا توجد رحلات محفوظة بعد.</p>'}</div>`;wireFav();cityImages();document.querySelectorAll('[data-open-trip]').forEach(b=>b.onclick=()=>{tripState={...savedTrips[+b.dataset.openTrip]};tripReady=true;location.hash='planner'});document.querySelectorAll('[data-delete-trip]').forEach(b=>b.onclick=()=>{savedTrips.splice(+b.dataset.deleteTrip,1);write('sg-trips',savedTrips);savedPage()})}
function budgetPage(){app.innerHTML=`<div class="wrap"><h1 class="page-title">${t('budget')} السياحية</h1><p>حاسبة بناءً على مبالغ تدخلها أنت. لا تمثل أسعارًا مؤكدة في السويد.</p><form id="budgetform" class="panel"><div class="formgrid" style="grid-template-columns:repeat(2,1fr)">${[['nights','عدد الليالي',2],['travellers','عدد المسافرين',1],['hotel','سكن المجموعة لكل ليلة SEK',0],['food','طعام للشخص يوميًا SEK',0],['transit','مواصلات للشخص يوميًا SEK',0],['activities','أنشطة للشخص يوميًا SEK',0],['intercity','تذاكر السفر للمجموعة SEK',0],['buffer','احتياط %',10]].map(([id,label,v])=>`<label>${label}<input id="${id}" type="number" min="${['travellers'].includes(id)?1:0}" max="${id==='buffer'?100:100000}" value="${v}" step="${['nights','travellers'].includes(id)?1:0.01}" required></label>`).join('')}</div><button class="primary" style="margin-top:20px">احسب الإجمالي</button></form><div id="budgetresult" class="panel" aria-live="polite"></div></div>`;const calc=()=>{const v=id=>+$('#'+id).value,n=v('nights'),p=v('travellers'),days=n+1,stay=n*v('hotel'),daily=days*p*(v('food')+v('transit')+v('activities')),base=stay+daily+v('intercity'),total=base*(1+v('buffer')/100);$('#budgetresult').innerHTML=`<p>الإجمالي حسب مدخلاتك</p><div class="budget-total">${total.toLocaleString('en-US',{maximumFractionDigits:2})} SEK</div><p>السكن ${stay.toFixed(2)} · المصروف اليومي للمجموعة ${daily.toFixed(2)} · السفر ${v('intercity').toFixed(2)}</p><p class="muted small">الحساب لـ ${days} أيام و${n} ليالٍ، يشمل ${v('buffer')}% احتياطًا. أدخل تكلفة السكن للمجموعة كلها. المبالغ الصفرية مدخلات وليست خدمات مجانية.</p>`};$('#budgetform').onsubmit=e=>{e.preventDefault();calc()};calc()}
function searchPage(query){const q=norm(query||'');app.innerHTML=`<div class="wrap"><h1 class="page-title">نتائج البحث</h1><form class="row" id="searchform"><input id="allq" class="search" value="${esc(query||'')}" placeholder="${t('search')}" aria-label="البحث الشامل"><button class="primary">بحث</button></form><div id="allresults"></div></div>`;const update=()=>{const n=norm($('#allq').value);if(!n){$('#allresults').innerHTML='<p class="empty">اكتب اسم مدينة أو معلم أو شركة نقل.</p>';return}const cs=cities.filter(c=>norm(c.name+' '+c.ar).includes(n)),ss=sights.filter(s=>norm(s.name+' '+s.desc).includes(n)),os=operators.filter(o=>norm(o.join(' ')).includes(n));$('#allresults').innerHTML=`<h2>المدن (${cs.length})</h2><div class="grid">${cs.map(cityCard).join('')}</div><h2>المعالم (${ss.length})</h2><div class="grid">${ss.map(sightCard).join('')}</div><h2>المواصلات (${os.length})</h2>${os.map(o=>`<div class="panel row"><b>${o[0]}</b><span>${o[2]}</span>${external(o[3],'المصدر الرسمي')}</div>`).join('')}${!cs.length&&!ss.length&&!os.length?'<p>لا توجد نتائج. جرّب الاسم السويدي أو العربي.</p>':''}`;wireFav();wireSights();cityImages()};$('#searchform').onsubmit=e=>{e.preventDefault();update()};update()}
function sourcesPage(){app.innerHTML=`<div class="wrap"><h1 class="page-title">المصادر وحالة البيانات</h1><p>إصدار أولي مستقل من Stockholm Guide • 15 أكتوبر 2026.</p><div class="panel"><h2>ما يعمل الآن</h2><p>البحث والفلاتر، دليل المدن والمعالم، حساب المسافة بخط مستقيم، المفضلة المحلية، اقتراح البرنامج ومشاركته، حساب الميزانية، مقارنة أسعار يدخلها المستخدم، الخريطة وروابط التخطيط الخارجية.</p><h2>ما يحتاج إلى تكامل لاحق</h2><p>أسعار التذاكر والمقاعد والمواعيد والتبديلات المباشرة، مدة الرحلة الفعلية، تصنيف الأرخص والأسرع. لا توجد مفاتيح API مضمنة ولا ندّعي وجود اتصال حي بهذه البيانات. ResRobot يتطلب مفتاحًا للبحث البرمجي؛ الرابط الخارجي لا يحتاج إلى مفتاح.</p>${external('https://www.trafiklab.se/api/our-apis/resrobot-v21/','Trafiklab / ResRobot')}${external('https://www.trafiklab.se/api/our-apis/resrobot-v21/deep-links/','توثيق روابط المسارات')}</div><div class="panel"><h2>المدن والسكان</h2><p>تسعة أرقام سكان من جدول SCB للتجمعات الحضرية في 31 ديسمبر 2023. هذه أرقام مؤرخة وليست تعدادًا حاليًا أو تعداد البلديات. بقية الأرقام غير مدخلة لحين التحقق. النبذات موجزة وتحتاج توسعة تاريخية موثقة.</p>${external(SCB,'إحصاء SCB 2023')}${external('https://visitsweden.com/where-to-go/','Visit Sweden')}${external('https://www.visitstockholm.com/','Visit Stockholm')}<p>إحداثيات مراكز المدن والمعالم إرشادية. مسافة Haversine بخط مستقيم؛ لا تُستخدم لتقدير زمن القيادة.</p></div><div class="panel"><h2>الصور والخرائط</h2><p>صور المدن من Wikimedia Commons، مختارة حسب المدينة ومحفوظة داخل الموقع لتقليل الاعتماد على تحميل الصور من خدمات خارجية. تظهر بيانات المصوّر والترخيص أسفل كل صورة، والقائمة الكاملة أدناه.</p>${external('https://commons.wikimedia.org/','Wikimedia Commons')}${external('https://www.openstreetmap.org/copyright','حقوق OpenStreetMap')}</div>${photoCredits()}<div class="panel"><h2>الخصوصية والتثبيت</h2><p>المفضلة والإعدادات والرحلات محفوظة محليًا. الخرائط والخطوط تُحمَّل من خدمات خارجية؛ صور المدن المختارة محفوظة مع الموقع. إذن الموقع يُطلب عند الضغط فقط؛ يرسل المتصفح طلبات بلاطات الخريطة إلى OpenStreetMap عند عرض منطقتك. لا توجد حسابات أو حجوزات داخل التطبيق.</p><p>على iPhone: افتح الموقع في Safari ← مشاركة ← إضافة إلى الشاشة الرئيسية. على Android: استخدم قائمة المتصفح ← تثبيت التطبيق أو إضافة إلى الشاشة الرئيسية.</p></div></div>`}
function notfound(){app.innerHTML='<div class="wrap empty"><h1>الصفحة غير موجودة</h1><a href="#home" class="btn primary">العودة إلى الرئيسية</a></div>'}
function render(){window.SGMotion?.cleanup();if(map){map.remove();map=null}nav();const raw=location.hash.slice(1)||'home',p=raw.split('?')[0],params=new URLSearchParams(raw.split('?')[1]||'');if(p.startsWith('city/'))cityPage(+p.split('/')[1]);else{const routes={home,cities:citiesPage,planner,tickets:ticketsPage,transport:transportPage,sights:sightsPage,map:mapPage,saved:savedPage,budget:budgetPage,passcompare:passCompare,sources:sourcesPage,search:()=>searchPage(params.get('q'))};(routes[p]||notfound)()}if(lang!=='ar'){const note=document.createElement('div');note.className='language-note';note.textContent=lang==='en'?'Navigation and trip fields are translated. Destination descriptions and detailed guides are currently in Arabic.':'Navigering och resefält är översatta. Detaljerade guider är tills vidare på arabiska.';app.prepend(note)}if(p==='planner'&&params.has('plan')){try{const pl=JSON.parse(params.get('plan'));if(cities[pl.city]){$('#it-city').value=pl.city;$('#it-days').value=Math.min(5,Math.max(1,+pl.days||1));if(['متنوعة','ثقافة وتاريخ','طبيعة ومشي','عائلة وأطفال'].includes(pl.interest))$('#it-interest').value=pl.interest;if(['اقتصادية','متوسطة','مرنة'].includes(pl.budget))$('#it-budget').value=pl.budget;makePlan()}}catch{toast('رابط الخطة غير صالح')}}window.scrollTo(0,0)}
$('#lang').onchange=e=>{lang=e.target.value;write('sg-lang',lang);render()};$('#theme').onclick=()=>{write('sg-dark',!read('sg-dark',false));nav()};$('#font').onclick=()=>{write('sg-large',!read('sg-large',false));nav()};window.addEventListener('hashchange',render);window.addEventListener('offline',()=>toast('أنت غير متصل. الخرائط والحجز يحتاجان إلى الإنترنت. بعض الصفحات والصور التي فتحتها قد تبقى متاحة دون اتصال.'));render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
